/// <summary>
/// CB256_PurchaseOrderReceiptDetails
/// Service class for purchase order packing slip posting task.
/// </summary>
class METPurchParmPackingSlipTaskService extends METSysOperationTaskService
{
    PurchParmTable  purchParmTable;
    ParmId          parmId;
    boolean         postRegisteredQuantity;
    METPurchParmPackingSlipContract contract;

}

Method.Source:
    /// <summary>
    /// Initializes the object.
    /// </summary>
    protected void initialise()
    {
        super();

        // get the topPickingProcessId from the contract
        contract = dataContract as METPurchParmPackingSlipContract;
    }

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METPurchParmPackingSlipContract</c>.
/// </param>
public void process(METPurchParmPackingSlipContract _contract)
{
    this.processInternal(_contract);
}

    /// <summary>
    /// Process the batch tasks.
    /// </summary>
    /// <param name = "_readPast">Read past table setting.</param>
    public void processTask(boolean _readPast)
    {
        purchParmTable.readPast(_readPast);              

        do
        {
            ttsbegin;
                      
            select firstOnly pessimisticlock purchParmTable
                where purchParmTable.METIsIntegration == NoYes::Yes
                &&    purchParmTable.ParmJobStatus == ParmJobStatus::Waiting;
            if (purchParmTable)
            {
                this.execute();
                //CB369 -ImportedItemsReceiving - start
                purchParmTable.ParmJobStatus = ParmJobStatus::Executed;
                purchParmTable.update();
                //CB369 -ImportedItemsReceiving - end
            }

            ttscommit;

            //CB256, CB257, CB260 – Purchase Order Receipt Details- new changes w.r.t cancel PO lines
            if (purchParmTable && !METPurchTable::find(purchParmTable.PurchId).POBackOrderSetting)
            {
                this.cancelPOLinesForZeroQtyAndSubmitToWorkfLow(purchParmTable.PurchId);
            }
        }
        while (purchParmTable);
    }

/// <summary>
/// Executes the main process.
/// </summary>
private void execute()
{
    parmId = purchParmTable.ParmId;
   
    //CB369 -ImportedItemsReceiving - start
    if (PurchTable::find(purchParmTable.PurchId).PurchStatus == PurchStatus::Invoiced)
    {
        this.findMatchingPOLinesAgainstGITOrderAndPost();
    }
    //CB369 -ImportedItemsReceiving - end
    else
    {
        this.registerPurchLine();
        this.postPackingSlip();
    }
}

    /// <summary>
    /// Updates <c>PurchParmTable</c> on error.
    /// </summary>
    protected void updateOnError()
    {
        PurchParmTable  purchParmTableUpdate;
        ParmJobStatus   jobStatus;
        int             retryCount,
                        maxRetry;
        
        purchParmTableUpdate = PurchParmTable::find(parmId, parmId);

        if (purchParmTableUpdate)
        {
            jobStatus = purchParmTableUpdate.ParmJobStatus;
            maxRetry = PurchParameters::find().METPOReceiptPostingRetiries;

            retryCount++;

            if (retryCount >= maxRetry)
            {
                jobStatus = ParmJobStatus::ContainErrors;
            }

            ttsbegin;

            purchParmTableUpdate.selectForUpdate(true);
        
            purchParmTableUpdate.METIntegrationRetries = retryCount;
            purchParmTableUpdate.ParmJobStatus = jobStatus;
            purchParmTableUpdate.update();
        
            ttscommit;
        }
    }

    /// <summary>
    /// Registers <c>PurchLine</c>.
    /// </summary>
    private void registerPurchLine()
    {
        METInventTransRegisterService   registerService;
        PurchParmLine                   parmLine;
        InventQty                       qtyReceiveNow;

        postRegisteredQuantity = false;
        // Loop through all lines for given ParmId and TableRefId
        while select parmLine
            where parmLine.ParmId == purchParmTable.ParmId
            &&    parmLine.TableRefId == purchParmTable.TableRefId
        {
            // Determine if line is CW item line.
            qtyReceiveNow = this.isCWItemLine(parmLine.PurchLineRecId) == true ? parmLine.InventNow : parmLine.ReceiveNow;

            // 1. Both CW and Qty present (CW update â‰  0, Qty â‰  0)
            if (qtyReceiveNow != 0 && parmLine.PdsCWPreviousReceiveNow != 0)
            {
                registerService = METInventTransRegisterService::contruct(parmLine.InventTransId, qtyReceiveNow, parmLine.PdsCWPreviousReceiveNow);
                registerService.register();
            }
            // 2. Qty present, CW zero (CW update == 0, Qty â‰  0)
            else if (qtyReceiveNow != 0 && parmLine.PdsCWPreviousReceiveNow == 0)
            {
                registerService = METInventTransRegisterService::contruct(parmLine.InventTransId, qtyReceiveNow, 0);
                registerService.register();
            }
            // 3. CW present, Qty zero (CW update â‰  0, Qty == 0)
            else if (qtyReceiveNow == 0 && parmLine.PdsCWPreviousReceiveNow != 0)
            {
                registerService = METInventTransRegisterService::contruct(parmLine.InventTransId, qtyReceiveNow, parmLine.PdsCWPreviousReceiveNow);
                registerService.register();
            }
        }
    }

    /// <summary>
    /// Checks if the line is for catch weight item.
    /// </summary>
    /// <param name = "_purchlineRecID">RecId of <c>PurchLine</c>.</param
    /// <returns>
    /// true if the line is for catch weight item, false otherwise.
    /// </returns>
    private boolean isCWItemLine(RecId _purchlineRecID)
    {
        boolean             isCWItemLine;
        PdsCatchWeightItem  pdsCatchWeightItem = PdsCatchWeightItem::find(PurchLine::findRecId(_purchlineRecID).ItemId);

        if (pdsCatchWeightItem.RecId)
        {
            isCWItemLine = true;
            postRegisteredQuantity = true;
        }
        else
        {
            isCWItemLine = false;
        }

        return isCWItemLine;
    }

    /// <summary>
    /// Posts packing slip.
    /// </summary>
    private void postPackingSlip()
    {
        PurchFormLetter         purchFormLetter;
        PurchParmUpdate         purchParmUpdate;
        PurchTable              purchTable;

        purchTable = PurchTable::find(purchParmTable.PurchId);
        purchParmUpdate = this.createPurchParmUpdate();

        purchFormLetter = PurchFormLetter::construct(DocumentStatus::PackingSlip);

        purchFormLetter.transDate(purchParmTable.TransDate);
        purchFormLetter.proforma(false);
        //BUG 2783619 Set to post only registered quantity if any CW item line was processed.
        if (postRegisteredQuantity)
        {
            purchFormLetter.specQty(PurchUpdate::Recorded);
        }
        else
        {
            purchFormLetter.specQty(PurchUpdate::All);
        }
        //BUG 2783619
        purchFormLetter.purchTable(purchTable);
        purchFormLetter.parmParmTableNum(purchParmTable.ParmId);
        purchFormLetter.parmId(purchParmTable.ParmId);
        purchFormLetter.purchParmUpdate(purchParmUpdate);
        purchFormLetter.run();
        
        if (contract.parmIsAutoGenerateCPNotice())
        {
            this.printVendorCPNReport(purchTable);
        }
    }

    /// <summary>
    /// Creates <c>PurhcParmUpdate</c> record before posting.
    /// </summary>
    /// <returns>
    /// <c>PurchParmUpdate</c>.
    /// </returns>
    private PurchParmUpdate createPurchParmUpdate()
    {
        PurchParmUpdate purchParmUpdate;
        PurchParameters purchParameters;
        VendParameters  vendParameters;

        purchParameters = PurchParameters::find();
        vendParameters  = VendParameters::find();

        purchParmUpdate = PurchParmUpdate::find(purchParmTable.ParmId);

        if (!purchParmUpdate.RecId)
        {
            purchParmUpdate.ParmId            = purchParmTable.ParmId;
            purchParmUpdate.DocumentStatus    = purchParmTable.Ordering;
            purchParmUpdate.SumBy             = purchParameters.SummaryUpdateBy;
            purchParmUpdate.SumPurchId        = '';
            purchParmUpdate.SumNum            = '';
            purchParmUpdate.SumIncludePending = NoYes::Yes;
            purchParmUpdate.CheckCreditMax    = vendParameters.CreditMaxCheck;
            purchParmUpdate.Storno            = vendParameters.CreditError;
            purchParmUpdate.LateSelection     = false;
            purchParmUpdate.CreditRemaining   = false;
            purchParmUpdate.Proforma          = false;

            purchParmUpdate.insert();
        }

        return purchParmUpdate;
    }

    /// CB369 -ImportedItemsReceiving 
    /// <summary>
    /// Find the matching PO lines in parm lines to get goods transist orders and post if found
    /// </summary>
    private void findMatchingPOLinesAgainstGITOrderAndPost()
    {
        PurchParmLine           purchParmLine;
        PurchLine               purchLine;
        ITMGoodsInTransitOrder  goodsInTransitOrder;
               
        while select purchParmLine
            where purchParmLine.OrigPurchId == purchParmTable.purchId
         join purchLine
            where purchLine.ItemId == purchParmLine.ItemId
            && purchLine.LineNumber == purchParmLine.LineNum
            && purchLine.PurchId == purchParmTable.purchId
        join goodsInTransitOrder
            where goodsInTransitOrder.InventTransIdRef == purchLine.InventTransId
            && goodsInTransitOrder.Status == ITMGoodsInTransitStatus::InTransit
        {
            if (goodsInTransitOrder)
            {
                
                if (purchLine.PurchUnit == "@MET:UOMEachUpperCase" || purchLine.PurchUnit == "@MET:UOMEachLowerCase")
                {
                    this.postGoodsInTransitOrder(goodsInTransitOrder);
                }
                else
                {
                    

                    PurchPrice convertedPurchPrice = UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(purchLine.PurchUnit).RecId,
                                                      UnitOfMeasure::findBySymbol("@MET:UOMEachUpperCase").RecId,
                                                      EcoResProduct::findByProductNumber(purchLine.ItemId).RecId).Factor;

                   
                    ttsbegin;
                    goodsInTransitOrder.selectForUpdate(true);
                    goodsInTransitOrder.Qty = convertedPurchPrice * goodsInTransitOrder.Qty;
                    goodsInTransitOrder.update();
                    ttscommit;

                    this.postGoodsInTransitOrder(goodsInTransitOrder);
                }
            }
            else
            {
                throw error(strFmt("@MET:NoGITOrdersAgainstPO", purchParmTable.PurchId));
            }
            
        }
    }

/// CB369 -ImportedItemsReceiving - start
/// <summary>
/// Post GIT orders
/// </summary>
/// <param name = "_goodsInTransitOrder">GIT order</param>
private void postGoodsInTransitOrder(ITMGoodsInTransitOrder _goodsInTransitOrder)
{
    ITMGoodsInTransitUpdateReceived updateReceived = ITMGoodsInTransitUpdateReceived::newGITOrder(_goodsInTransitOrder, _goodsInTransitOrder.Qty,
                                                                                                              DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    
    updateReceived.run();
}

    /// <summary>
    /// Cancel PO lines for zero qty on parm lines and submit to workflow
    /// </summary>
    /// <param name = "_purchId">PurchId</param>
    public void cancelPOLinesForZeroQtyAndSubmitToWorkfLow(PurchId _purchId)
    {
        #OCCRetryCount

        try
        {
            PurchParmLine   purchParmLine;
            PurchLine       purchLine,purchLineUpdate;
            PurchTable      purchTable;

            if (!purchParmTable.PurchId)
            {
                throw error("@MET:PurchParmTableMissingPurchId");
            }
                
            purchTable = PurchTable::find(purchParmTable.PurchId, true);

            if (purchTable && !purchTable.SkipVersioning && purchTable.ChangeRequestRequired)
            {
                ttsbegin;
                purchTable.SkipVersioning = true;
                purchTable.ChangeRequestRequired = NoYes::No;
                purchTable.update();
                ttscommit;
            }

            PurchCancel purchCancel = PurchCancel::METconstruct();
            
            ttsbegin;
            while select LineNum, ItemId from purchParmLine
                where purchParmLine.ParmId ==  purchParmTable.ParmId
                && purchParmLine.PdsCWPreviousReceiveNow == 0
                && purchParmLine.PdsCWReceiveNow == 0
                && purchParmLine.ReceiveNow == 0
            join purchLine
                where purchLine.PurchId == purchParmTable.PurchId
                && purchLine.LineNumber == purchParmLine.LineNum
                && purchLine.ItemId == purchParmLine.ItemId
                && purchLine.IsDeleted == NoYes::No
                && purchLine.PurchStatus != PurchStatus::Canceled
            {
                purchLineUpdate = PurchLine::findRecId(purchLine.RecId,true);
                purchCancel.metCancelPurchLine(purchLineUpdate);
            }
            ttscommit;          
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            throw error("@SYS93835");
        }

    }

    /// <summary>
    /// Initiates the printing or batch scheduling of the Vendor Continuing Permission Notice (CPN) report
    /// for a given purchase order, based on specific business conditions.
    /// </summary>
    /// <param name="_purchTable">The PurchTable record representing the purchase order.</param>
    /// <remarks>
    /// This method checks if the purchase order is marked as 'UnderBond' and 'VendorReturn',
    /// and if it contains at least one line with a negative quantity. If these conditions are met,
    /// it either adds the report to an existing batch (if executing in batch mode),
    /// or creates a new batch header and schedules the report for execution.
    /// </remarks>
    private void printVendorCPNReport(PurchTable _purchTable)
    {
        METPurchTable metPurchTable = METPurchTable::find(_purchTable.PurchId);
        
        if (metPurchTable.UnderBond && metPurchTable.VendorReturn)
        {
            PurchLine purchLineNegative;

            select firstonly RecId from purchLineNegative
                    where purchLineNegative.PurchId == _purchTable.PurchId
                    && purchLineNegative.PurchQty < 0;

            if (purchLineNegative.RecId)
            {
                args args = new Args();
                args.record(_purchTable);
                if (isExecutingInBatch)
                {
                    batchHeader.addRuntimeTask(this.getVendorCPNController(args), headerTaskId);
                    batchHeader.save();
                }
                else
                {
                    BatchHeader cpnBatch = BatchHeader::construct();
                    cpnBatch.parmCaption(strFmt("@MET:VendorCPNPurchID", _purchTable.PurchId));
                    cpnBatch.addTask(this.getVendorCPNController(args));
                    cpnBatch.save();
                }
            }
        }
    }

    /// <summary>
    /// Constructs and configures the report controller for the Vendor Continuing Permission Notice (CPN) report.
    /// </summary>
    /// <param name="_args">An Args object containing the PurchTable record to be passed to the report.</param>
    /// <returns>
    /// A fully configured instance of METPOContinuingPermissionNoticeController,
    /// with the report name, dialog settings, and data contract parameters set.
    /// </returns>
    /// <remarks>
    /// This method retrieves the appropriate PrintMgmtReportFormat for the CPN report,
    /// suppresses the dialog for automated execution, and sets the PurchId on the data contract.
    /// </remarks>
    private METPOContinuingPermissionNoticeController getVendorCPNController(Args _args)
    {
        METPOContinuingPermissionNoticeController controller =
            METPOContinuingPermissionNoticeController::construct();
        
        PrintMgmtDocumentType type =  PrintMgmtDocumentType::METPOContinuingPermissionNote;
        PrintMgmtReportFormat printMgmtReportFormat = PrintMgmtReportFormat::findSystem(type);

        if (!printMgmtReportFormat.RecId)
        {
            select Name from printMgmtReportFormat
                where printMgmtReportFormat.DocumentType == type;
        }

        controller.parmReportName(printMgmtReportFormat.Name);
        controller.parmArgs(_args);
        controller.parmShowDialog(false);
        controller.parmLoadFromSysLastValue(false);
        controller.parmDialogCaption("@MET:METCPNotice");

        METPOContinuingPermissionNoticeContract contractLoc = controller.getDataContractObject();
        PurchTable purchTable = _args.record();
        contractLoc.parmPurchId(purchTable.PurchId);

        return controller;
    }
